Stack: Node 22+ with Express and the built-in `node:sqlite`. Hashing uses stdlib `crypto.scrypt`, so Express is the only dependency.

```js
// server.js — npm i express ; node server.js
import express from 'express';
import { DatabaseSync } from 'node:sqlite';
import { scrypt, randomBytes, timingSafeEqual, createHash } from 'node:crypto';
import { promisify } from 'node:util';

const scryptAsync = promisify(scrypt);
const db = new DatabaseSync('auth.db');
db.exec(`
  PRAGMA journal_mode = WAL;
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY,
    email TEXT NOT NULL UNIQUE,
    pw_hash TEXT NOT NULL,
    created_at INTEGER NOT NULL
  );
  CREATE TABLE IF NOT EXISTS sessions (
    token_hash TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    expires_at INTEGER NOT NULL
  );
  CREATE TABLE IF NOT EXISTS failed_logins (
    key TEXT PRIMARY KEY,          -- 'ip:<addr>' or 'email:<addr>'
    count INTEGER NOT NULL,
    window_start INTEGER NOT NULL,
    locked_until INTEGER NOT NULL DEFAULT 0
  );
`);

// ---- password hashing (scrypt, N=2^15) ----
const SCRYPT = { N: 1 << 15, r: 8, p: 1, maxmem: 64 * 1024 * 1024 };
async function hashPassword(pw) {
  const salt = randomBytes(16);
  const key = await scryptAsync(pw, salt, 64, SCRYPT);
  return `scrypt$${SCRYPT.N}$${salt.toString('base64')}$${key.toString('base64')}`;
}
async function verifyPassword(pw, stored) {
  const [, N, saltB64, keyB64] = stored.split('$');
  const expected = Buffer.from(keyB64, 'base64');
  const key = await scryptAsync(pw, Buffer.from(saltB64, 'base64'), expected.length, { ...SCRYPT, N: +N });
  return timingSafeEqual(key, expected);
}
// Burn equal time for unknown emails → no user enumeration via timing
const DUMMY_HASH = await hashPassword(randomBytes(16).toString('hex'));

// ---- sessions: random token in cookie, only its SHA-256 in DB ----
const SESSION_TTL = 7 * 24 * 3600 * 1000;
const sha256 = (s) => createHash('sha256').update(s).digest('hex');
function issueSession(res, userId) {
  const token = randomBytes(32).toString('base64url');
  db.prepare('INSERT INTO sessions VALUES (?, ?, ?)').run(sha256(token), userId, Date.now() + SESSION_TTL);
  res.cookie('sid', token, {
    httpOnly: true, secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax', maxAge: SESSION_TTL, path: '/',
  });
}
function parseCookie(req, name) {
  const m = (req.headers.cookie || '').match(new RegExp(`(?:^|;\\s*)${name}=([^;]+)`));
  return m ? decodeURIComponent(m[1]) : null;
}
function requireAuth(req, res, next) {
  const token = parseCookie(req, 'sid');
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  const row = db.prepare(
    'SELECT u.id, u.email, s.expires_at FROM sessions s JOIN users u ON u.id = s.user_id WHERE s.token_hash = ?'
  ).get(sha256(token));
  if (!row || row.expires_at < Date.now()) return res.status(401).json({ error: 'Unauthorized' });
  req.user = { id: row.id, email: row.email };
  next();
}

// ---- rate limiting on failed logins (per IP and per email) ----
const WINDOW = 15 * 60 * 1000, MAX_FAILS = { ip: 20, email: 5 }, LOCK = 15 * 60 * 1000;
function lockedFor(key) {
  const row = db.prepare('SELECT locked_until FROM failed_logins WHERE key = ?').get(key);
  return row && row.locked_until > Date.now() ? row.locked_until - Date.now() : 0;
}
function recordFailure(key, max) {
  const now = Date.now();
  const row = db.prepare('SELECT * FROM failed_logins WHERE key = ?').get(key);
  if (!row || now - row.window_start > WINDOW) {
    db.prepare('INSERT OR REPLACE INTO failed_logins VALUES (?, 1, ?, 0)').run(key, now);
  } else {
    const count = row.count + 1;
    db.prepare('UPDATE failed_logins SET count = ?, locked_until = ? WHERE key = ?')
      .run(count, count >= max ? now + LOCK : 0, key);
  }
}
const clearFailures = (key) => db.prepare('DELETE FROM failed_logins WHERE key = ?').run(key);

// ---- validation ----
const normEmail = (e) => (typeof e === 'string' ? e.trim().toLowerCase() : '');
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
function validate(email, password) {
  if (!EMAIL_RE.test(email) || email.length > 254) return 'Invalid email';
  if (typeof password !== 'string' || password.length < 8) return 'Password must be at least 8 characters';
  if (password.length > 256) return 'Password too long'; // caps hashing cost (DoS)
  return null;
}

// ---- routes ----
const app = express();
app.set('trust proxy', 1); // only if behind exactly one reverse proxy; else remove
app.use(express.json({ limit: '10kb' }));

app.post('/signup', async (req, res) => {
  const email = normEmail(req.body?.email), { password } = req.body ?? {};
  const err = validate(email, password);
  if (err) return res.status(400).json({ error: err });
  try {
    const { lastInsertRowid } = db.prepare('INSERT INTO users (email, pw_hash, created_at) VALUES (?, ?, ?)')
      .run(email, await hashPassword(password), Date.now());
    issueSession(res, Number(lastInsertRowid));
    res.status(201).json({ ok: true });
  } catch (e) {
    if (String(e.message).includes('UNIQUE')) return res.status(409).json({ error: 'Email already registered' });
    throw e;
  }
});

app.post('/login', async (req, res) => {
  const email = normEmail(req.body?.email), password = req.body?.password;
  if (typeof password !== 'string' || password.length > 256 || !email)
    return res.status(400).json({ error: 'Invalid request' });

  const ipKey = `ip:${req.ip}`, emailKey = `email:${email}`;
  const wait = Math.max(lockedFor(ipKey), lockedFor(emailKey));
  if (wait) {
    res.set('Retry-After', Math.ceil(wait / 1000));
    return res.status(429).json({ error: 'Too many failed attempts. Try again later.' });
  }

  const user = db.prepare('SELECT id, pw_hash FROM users WHERE email = ?').get(email);
  const ok = await verifyPassword(password, user?.pw_hash ?? DUMMY_HASH) && !!user;
  if (!ok) {
    recordFailure(ipKey, MAX_FAILS.ip);
    recordFailure(emailKey, MAX_FAILS.email);
    return res.status(401).json({ error: 'Invalid email or password' });
  }
  clearFailures(emailKey);
  issueSession(res, user.id);
  res.json({ ok: true });
});

app.post('/logout', (req, res) => {
  const token = parseCookie(req, 'sid');
  if (token) db.prepare('DELETE FROM sessions WHERE token_hash = ?').run(sha256(token));
  res.clearCookie('sid', { path: '/' });
  res.json({ ok: true });
});

app.get('/me', requireAuth, (req, res) => res.json(req.user));

// purge expired sessions hourly
setInterval(() => db.prepare('DELETE FROM sessions WHERE expires_at < ?').run(Date.now()), 3600e3).unref();

app.use((err, req, res, next) => { console.error(err); res.status(500).json({ error: 'Internal error' }); });
app.listen(3000, () => console.log('listening on :3000'));
```

Security properties:
- Session tokens are stored only as SHA-256 hashes, so a database leak does not expose live sessions.
- Unknown emails still run a full scrypt check, which closes the timing side channel.
- Each email gets its own lockout, which stops guessing against one account. The per-IP limit slows spraying across many accounts.
- Signup returns 409 for a duplicate email, which reveals that the account exists. To prevent that, always return a generic "check your inbox" response and send the details by email.
- Run behind HTTPS in production so the `secure` cookie flag is set. `SameSite=Lax` blocks most cross-site request forgery, but you still need CSRF tokens if you accept state-changing GET requests or support old browsers.

Skipped: email verification, password reset, and session rotation on privilege change. Add them before accepting real users.
